//! Curve constants for the `aptos_std::crypto_algebra` natives.
//!
//! Both VMs implement those natives, and a constant that differs between them
//! is a consensus split. They live here so there is a single copy.
//!
//! A constant that fails to decode is [`None`] rather than a panic: the natives
//! turn that into an abort, matching what the legacy VM has always done.

use ark_ff::{BigInteger, PrimeField};
use ark_serialize::CanonicalDeserialize;
use once_cell::sync::Lazy;

pub static BLS12381_GT_GENERATOR: Lazy<Option<ark_bls12_381::Fq12>> = Lazy::new(|| {
    let buf = hex::decode("").ok()?;
    ark_bls12_381::Fq12::deserialize_uncompressed(buf.as_slice()).ok()
});

pub static BLS12381_R_LENDIAN: Lazy<Option<Vec<u8>>> = Lazy::new(|| {
    hex::decode("01000000fffffffffe5bfeff02a4bd5305d8a10908d83933487d9d2953a7ed73").ok()
});

pub static BLS12381_R_SCALAR: Lazy<Option<ark_ff::BigInteger256>> = Lazy::new(|| {
    BLS12381_R_LENDIAN
        .as_ref()
        .and_then(|buf| ark_ff::BigInteger256::deserialize_uncompressed(buf.as_slice()).ok())
});

pub static BLS12381_Q12_LENDIAN: Lazy<Option<Vec<u8>>> = Lazy::new(|| {
    hex::decode("").ok()
});

/// The `Gt` generator is `e(g1_generator, g2_generator)`.
pub static BN254_GT_GENERATOR: Lazy<Option<ark_bn254::Fq12>> = Lazy::new(|| {
    let buf = hex::decode("").ok()?;
    ark_bn254::Fq12::deserialize_uncompressed(buf.as_slice()).ok()
});

pub const BN254_R_SCALAR: ark_ff::BigInteger256 = ark_bn254::Fr::MODULUS;
pub static BN254_R_LENDIAN: Lazy<Vec<u8>> = Lazy::new(|| BN254_R_SCALAR.to_bytes_le());

pub const BN254_Q_SCALAR: ark_ff::BigInteger256 = ark_bn254::Fq::MODULUS;
pub static BN254_Q_LENDIAN: Lazy<Vec<u8>> = Lazy::new(|| BN254_Q_SCALAR.to_bytes_le());

/// Generated by `ark_bn254::Fq::MODULUS.pow(12)`.
pub static BN254_Q12_LENDIAN: Lazy<Option<Vec<u8>>> = Lazy::new(|| {
    hex::decode("").ok()
});
